// Runtime config + API routing. Values come from /env.js:
//   Cloudflare Pages: generated by _worker.js from environment variables (API_BASE empty -> /api proxy).
//   GitHub Pages: generated at build time (API_BASE = Supabase Functions URL, direct mode).
// No secrets here: the publishable key is public by design and protected by RLS.
(function () {
  var env = window.LAMSA_ENV || {};
  var base = String(env.API_BASE || "").replace(/\/+$/, "");
  var supa = String(env.SUPABASE_URL || "").replace(/\/+$/, "");
  var key = env.SUPABASE_PUBLISHABLE_KEY || "";
  window.LAMSA_CONFIG = {
    SUPABASE_URL: supa || "__SUPABASE_URL__",
    SUPABASE_PUBLISHABLE_KEY: key || "__SUPABASE_PUBLISHABLE_KEY__",
    SITE_URL: env.SITE_URL || location.origin,
    BASE_PATH: env.BASE_PATH || "",
    BRAND_NAME: "LAMSA",
    CURRENCY: "EGP",
    LEGAL_VERSION: "2026-09-11",
    BUILD_VERSION: "cf-v40-fresh-start"
  };
  /** URL of a backend function: Worker proxy (/api/name) or Supabase directly. */
  window.LAMSA_API = function (name) { return (base || "/api") + "/" + encodeURIComponent(name); };
  /** Extra headers for direct mode (Supabase needs the publishable key). */
  window.LAMSA_API_HEADERS = function (h) { h = h || {}; if (base && key) h.apikey = key; return h; };
  /** Signed-upload URL for order files / WOW replies. */
  window.LAMSA_UPLOAD_URL = function (bucket, path, token) {
    var p = String(path).split("/").map(encodeURIComponent).join("/");
    if (base && supa) return supa + "/storage/v1/object/upload/sign/" + bucket + "/" + p + "?token=" + encodeURIComponent(token);
    return (bucket === "order-uploads" ? "/upload/order" : "/upload/wow-reply") + "?path=" + encodeURIComponent(path) + "&token=" + encodeURIComponent(token);
  };
})();
